    /**
     * 按迁移键查询全部快照（按写入顺序）。
     */
    public List<LocationMoveSealSnapshot> findByMoveKey(String moveKey) {
        return jdbc.query(
                "SELECT * FROM location_move_seal_snapshot WHERE move_key = ? ORDER BY id",
